// Laboratory end-to-end check of CA proposals and issuer certificates
// (migration 0025, ADR-0013) through Keycloak sign-ins and the management
// API of the Compose stack. The root key is generated by OpenSSL with
// scripts/lab/create-lab-root.sh into the ignored .lab-keys/; only the
// certificate is sent. Run with .env.lab loaded, after compose-smoke.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { requiredEnv, signIn } from './keycloak-login.mjs';

const realm = 'http://127.0.0.1:8080/realms/trust-lab';
const api = 'http://127.0.0.1:8081';
const repository = fileURLToPath(new URL('../../', import.meta.url));
const suffix = randomUUID().slice(0, 8);
const name = `E2E Lab Root ${suffix}`;
const results = [];

async function token(username, envName) {
  const session = await signIn(realm, username, requiredEnv(envName));
  assert.ifError(session.error);
  return session.access_token;
}

async function send(method, path, accessToken, body, key = randomUUID()) {
  const headers = { authorization: `Bearer ${accessToken}` };
  if (body !== undefined) Object.assign(headers, { 'content-type': 'application/json', 'idempotency-key': key });
  const response = await fetch(`${api}${path}`, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  const text = await response.text();
  return { status: response.status, replayed: response.headers.get('idempotent-replayed') === 'true',
    body: text ? JSON.parse(text) : null };
}

async function check(label, run) {
  await run();
  results.push(label);
  console.log(`ok - ${label}`);
}

// Generates a root outside the platform, as an administrator would.
function labRoot(displayName) {
  return execFileSync('sh', ['scripts/lab/create-lab-root.sh', displayName], { cwd: repository }).toString();
}

const admin = await token('lab-ca-admin', 'TRUST_LAB_PW_CA_ADMIN');
const operator = await token('lab-operator', 'TRUST_LAB_PW_OPERATOR');
const reader = await token('lab-reader', 'TRUST_LAB_PW_READER');
const proposal = (displayName = name) => ({ display_name: displayName, policy_version: 'v1', suite_id: 'ecdsa-p256-sha256' });
let caId;

try {
  await check('only an administrator proposes a CA, once per idempotency key', async () => {
    assert.equal((await send('POST', '/v1/ca-proposals', operator, proposal())).status, 403);
    assert.equal((await send('POST', '/v1/ca-proposals', admin, { ...proposal(), suite_id: 'ecdsa-p384-sha384' })).status, 422);
    const key = randomUUID();
    const created = await send('POST', '/v1/ca-proposals', admin, proposal(), key);
    assert.deepEqual([created.status, created.body.lifecycle_status], [201, 'PROPOSED']);
    caId = created.body.ca_id;
    const replay = await send('POST', '/v1/ca-proposals', admin, proposal(), key);
    assert.deepEqual([replay.status, replay.replayed, replay.body.ca_id], [200, true, caId]);
  });

  const path = () => `/v1/ca-proposals/${caId}/issuer-certificate`;
  await check('a root for another name, or a non-administrator, is refused', async () => {
    const other = labRoot(`E2E Other Root ${suffix}`);
    assert.equal((await send('POST', path(), admin, { certificate_pem: other })).status, 422);
    assert.equal((await send('POST', path(), operator, { certificate_pem: other })).status, 403);
    assert.equal((await send('POST', path(), admin, { certificate_pem: other, private_key_pem: 'x' })).status, 400);
  });

  await check('the OpenSSL root of the proposal is verified and recorded once', async () => {
    const pem = labRoot(name);
    const registered = await send('POST', path(), admin, { certificate_pem: pem });
    assert.deepEqual([registered.status, registered.body.lifecycle_status], [201, 'KEY_ATTESTED']);
    const fingerprint = execFileSync('openssl', ['x509', '-outform', 'DER'], { input: pem });
    const expected = execFileSync('openssl', ['dgst', '-sha256', '-r'], { input: fingerprint }).toString().split(' ')[0];
    assert.equal(registered.body.certificate_sha256, expected);
    // The proposal already has its certificate: any other root is refused.
    assert.equal((await send('POST', path(), admin, { certificate_pem: labRoot(`${name}B`) })).status, 409);
  });

  await check('administrators list proposals; readers cannot and see no new CA', async () => {
    const listed = await send('GET', '/v1/ca-proposals', admin);
    assert.equal(listed.status, 200);
    const mine = listed.body.find(item => item.ca_id === caId);
    assert.deepEqual([mine.lifecycle_status, mine.display_name, mine.custody], ['KEY_ATTESTED', name, 'lab-software-file']);
    assert.equal((await send('GET', '/v1/ca-proposals', reader)).status, 403);
    const cas = await send('GET', '/v1/cas', reader);
    assert.ok(cas.body.every(ca => ca.ca_id !== caId));
  });
} finally {
  // Software keys from this run are not kept.
  for (const slug of [name, `E2E Other Root ${suffix}`, `${name}B`]) {
    const file = slug.toLowerCase().replaceAll(' ', '-').replaceAll('.', '-');
    rmSync(`${repository}.lab-keys/ca-root-${file}.pem`, { force: true });
    rmSync(`${repository}.lab-keys/ca-root-${file}.crt`, { force: true });
  }
}

console.log(`Laboratory CA proposal suite passed: ${results.length} cases (proposal ${caId}).`);
